#include <iostream>
#include <memory>
struct Buffer { int* p; Buffer(): p(new int[4]) { std::cout << "alloc\n"; } ~Buffer(){ delete[] p; std::cout << "free\n"; } };
struct MyDeleter { void operator()(Buffer* b) const { std::cout << "mydelete\n"; delete b; } };
int main() {
    { std::unique_ptr<Buffer, MyDeleter> u(new Buffer(), MyDeleter()); }  // 作用域结束自动调用 MyDeleter
    std::cout << "after scope";
}
